package com.nigson.experience.lead;

import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.PrivateWorkload;
import java.net.*;
import java.net.http.*;
import java.time.Duration;
import java.util.*;
import java.util.function.Function;
import org.springframework.core.env.Environment;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Exact Commerce owner API for current market/SKU quote-request eligibility. */
public final class HttpQuoteSkuEligibilityClient implements QuoteLeadAssociation.SkuEligibilityPort {
 private final URI base;private final Function<PrivateWorkload.Route,String> token;private final HttpClient http;
 HttpQuoteSkuEligibilityClient(URI base,Function<PrivateWorkload.Route,String> token,HttpClient http){this.base=base;this.token=token;this.http=http;}
 public static HttpQuoteSkuEligibilityClient from(Environment e){String raw=e.getRequiredProperty("NIGSON_COMMERCE_PRIVATE_URL"),issuer=e.getRequiredProperty("NIGSON_OIDC_ISSUER"),client=e.getRequiredProperty("NIGSON_QUOTE_CATALOGUE_WORKLOAD_CLIENT_ID"),secret=e.getRequiredProperty("NIGSON_QUOTE_CATALOGUE_WORKLOAD_CLIENT_SECRET"),env=e.getRequiredProperty("APP_ENV");URI base=URI.create(raw),tokenUri=URI.create(issuer+"/protocol/openid-connect/token");if(!Set.of("http","https").contains(base.getScheme())||base.getHost()==null||base.getRawQuery()!=null||base.getRawFragment()!=null||!Set.of("http","https").contains(tokenUri.getScheme())||tokenUri.getHost()==null||client.isBlank()||secret.isBlank()||!Set.of("local","test").contains(env)&&(!"https".equals(base.getScheme())||!"https".equals(tokenUri.getScheme())))throw new IllegalArgumentException("QUOTE_CATALOGUE_CONFIGURATION_INVALID");HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();return new HttpQuoteSkuEligibilityClient(base,r->{try{String form="grant_type=client_credentials&scope="+URLEncoder.encode(r.scope(),java.nio.charset.StandardCharsets.UTF_8);String auth=Base64.getEncoder().encodeToString((client+":"+secret).getBytes(java.nio.charset.StandardCharsets.UTF_8));var req=HttpRequest.newBuilder(tokenUri).timeout(Duration.ofSeconds(3)).header("Authorization","Basic "+auth).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(form)).build();var res=http.send(req,HttpResponse.BodyHandlers.ofByteArray());if(res.statusCode()!=200||res.body().length>8192)return null;return EventCodec.JSON.readTree(res.body()).path("access_token").asString(null);}catch(Exception failure){return null;}},http);}
 public List<QuoteLeadValues.EligibleSku> validate(UUID party,UUID market,UUID organization,List<QuoteLeadValues.Product> products){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("COMMERCE_HTTP_INSIDE_EXPERIENCE_TRANSACTION");var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-206")&&r.owner().equals("commerce")&&r.client().equals("nigson-experience")).findFirst().orElseThrow(()->new IllegalStateException("API_206_ROUTE_MISSING"));String bearer=token.apply(route);if(bearer==null||bearer.isBlank()||bearer.length()>16384)throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);var payload=new LinkedHashMap<String,Object>();payload.put("partyId",party);payload.put("marketId",market);payload.put("organizationId",organization);payload.put("items",products.stream().map(p->Map.of("skuId",p.skuId(),"quantity",p.quantity().toPlainString())).toList());byte[] body=EventCodec.JSON.writeValueAsBytes(payload);var req=HttpRequest.newBuilder(base.resolve("/internal/v1/quote-sku-eligibility")).timeout(Duration.ofSeconds(5)).header("Authorization","Bearer "+bearer).header("Content-Type","application/json").header("Accept","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();try{var res=http.send(req,HttpResponse.BodyHandlers.ofByteArray());if(res.body().length>16384||res.statusCode()!=200)throw new Problem.Failure(res.statusCode()==503?ProblemCode.PROVIDER_UNAVAILABLE:ProblemCode.QUOTE_RULE_VIOLATION);var json=EventCodec.JSON.readTree(res.body());if(!json.propertyNames().equals(Set.of("items"))||!json.path("items").isArray()||json.path("items").size()!=products.size())throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);var result=new ArrayList<QuoteLeadValues.EligibleSku>();var seen=new HashSet<UUID>();for(var item:json.path("items")){if(!item.propertyNames().equals(Set.of("skuId","quantityScale"))||!item.path("skuId").isString()||!item.path("quantityScale").canConvertToInt())throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);UUID sku=ApiValues.uuid(item.path("skuId").asString());int scale=item.path("quantityScale").asInt();if(scale<0||scale>3||!seen.add(sku))throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);result.add(new QuoteLeadValues.EligibleSku(sku,scale));}if(!seen.equals(products.stream().map(QuoteLeadValues.Product::skuId).collect(java.util.stream.Collectors.toSet())))throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);for(var p:products){var eligible=result.stream().filter(s->s.skuId().equals(p.skuId())).findFirst().orElseThrow();if(p.quantity().scale()>eligible.quantityScale())throw new Problem.Failure(ProblemCode.QUOTE_RULE_VIOLATION);}return List.copyOf(result);}catch(Problem.Failure failure){throw failure;}catch(Exception uncertain){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}}
}
